import React from 'react';
import {AbsoluteFill,interpolate,Easing,clamp,useS,en,words,FONT} from './kit';

const GOLD='#ffc96c',CYAN='#67dcff',WHITE='#eaf6ff',DEEP='#050c20';
const progress=(s:number,a:number,b:number)=>interpolate(s,[a,b],[0,1],clamp);
const show=(s:number,a:number,b:number)=>Math.min(progress(s,a,a+.30),1-progress(s,b-.24,b));
const pulse=(s:number,t:number)=>s<t?0:Math.exp(-(s-t)*5)*Math.sin((s-t)*22);
const T={
  sol:0, desaparecer:en('desapareciera'), ocho:en('ocho'), luz:en('luz'),
  tierra:en('Tierra'), ultimo:en('último'), foton:en('rayo'),
  gravedad:en('gravedad'), orbita:en('órbita'), juntos:en('Así'),
  informacion:en('información',2), descubrir:en('descubrirías'), tiempo:en('universo')
};
const stars=Array.from({length:98},(_,i)=>({x:(i*283+67)%1080,y:(i*491+31)%1920,r:1+(i%3),p:i*.72}));
const Disc:React.FC<{x:number;y:number;r:number;lit?:boolean;light?:number;z?:number;s:number}> = ({x,y,r,lit=true,light=1,z=0,s})=><g>
 <defs><radialGradient id={'p'+(lit?'lit':'dark')} cx="35%" cy="25%"><stop offset="0%" stopColor={lit?'#fff8c9':'#4bc6ec'}/><stop offset="55%" stopColor={lit?'#ffad38':'#276ca4'}/><stop offset="100%" stopColor={lit?'#bd3f10':'#0b203b'}/></radialGradient></defs>
 <circle cx={x} cy={y} r={r*1.5} fill={lit?'#ffa73f':'#5adfff'} opacity={.065*light}/>
 <circle cx={x} cy={y} r={r} fill={'url(#p'+(lit?'lit':'dark')+')'} stroke={lit?'#ffdc79':'#66d0ed'} strokeWidth={2}/>
 <ellipse cx={x-r*.21} cy={y-r*.1} rx={r*.73} ry={r*.19} fill="#ffffff" opacity={lit?.09:.21} transform={'rotate(-27 '+x+' '+y+')'}/>
 </g>;
const Cap:React.FC<{t:string;sub?:string;c?:string;op?:number}> = ({t,sub,c=WHITE,op=1})=><div style={{position:'absolute',left:60,right:60,top:1280,opacity:op,textAlign:'center'}}>
  <div style={{fontFamily:FONT,fontSize:70,fontWeight:900,color:c,letterSpacing:1,textShadow:'0px 6px 24px #000'}}>{t}</div>
  {sub&&<div style={{fontFamily:FONT,fontSize:31,letterSpacing:4,color:'#b4d1e8',marginTop:14,fontWeight:650}}>{sub}</div>}
 </div>;
export const SUBS={arriba:1580,size:53,acento:GOLD};
export const Escena:React.FC=()=>{
 const {s}=useS();
 const sunFade=1-progress(s,T.desaparecer,T.desaparecer+.45);
 const travel=progress(s,T.ocho,T.tierra);
 const g=progress(s,T.gravedad,T.orbita);
 const together=progress(s,T.juntos,T.informacion+1);
 const finale=progress(s,T.descubrir,T.tiempo+.9);
 const now= Math.max(0,Math.min(words.length-1,words.findIndex((w,i)=>i===words.length-1||words[i+1].t>s)));
 const camera=1+Math.sin(s*.35)*.025+(.11*travel)+(.06*g);
 const rot=s*.2;
 const current=s<T.ocho?0:s<T.ultimo?1:s<T.foton?2:s<T.gravedad?3:s<T.juntos?4:s<T.descubrir?5:6;
 const steps=[{n:'DESAPARECE',detail:'¿CUÁNDO LO NOTARÍAS?',c:GOLD},{n:'8 MIN 20 S',detail:'LA LUZ SIGUE VIAJANDO',c:GOLD},{n:'ÚLTIMA LUZ',detail:'EL VIAJE CONTINÚA',c:CYAN},{n:'GRAVEDAD',detail:'NO CAMBIA AL INSTANTE',c:CYAN},{n:'MISMA VELOCIDAD',detail:'LAS SEÑALES VIAJAN',c:GOLD},{n:'LA TIERRA',detail:'AÚN NO LO SABE',c:CYAN},{n:'8:20',detail:'AHORA LLEGA LA NOTICIA',c:GOLD}];
 const v=steps[current];
 const earthX=786+Math.cos(rot)*17,earthY=900+Math.sin(rot)*18;
 return <AbsoluteFill style={{background:'radial-gradient(ellipse at 45% 42%,#12294b 0%,#08152c 50%,#020713 95%)',overflow:'hidden'}}>
 <AbsoluteFill style={{background:'linear-gradient(150deg,rgba(10,51,99,.15),rgba(3,5,13,.2))'}}/>
 <svg viewBox="0 0 1080 1920" width="1080" height="1920" style={{position:'absolute',transform:'scale('+camera+')',transformOrigin:'540px 900px'}}>
  <defs>
    <linearGradient id="beam"><stop stopColor={GOLD}/><stop offset="1" stopColor={CYAN}/></linearGradient>
    <filter id="gl"><feGaussianBlur stdDeviation="22"/></filter>
  </defs>
  {stars.map((p,i)=><circle key={i} cx={p.x+Math.sin(s*.11+p.p)*8} cy={p.y+Math.cos(s*.12+p.p)*6} r={p.r} fill={i%5===0?GOLD:WHITE} opacity={.12+.35*(.5+.5*Math.sin(s*1.5+p.p))}/>)}
  <ellipse cx="540" cy="900" rx="360" ry="145" stroke={CYAN} strokeWidth="3" fill="none" opacity={.15+.18*g} transform="rotate(-10 540 900)"/>
  <ellipse cx="540" cy="900" rx="360" ry="145" stroke={CYAN} strokeWidth="1" fill="none" strokeDasharray="8 18" opacity={.5+.25*Math.sin(s)}/>
  <path d="M 325 900 Q 530 730 786 900" fill="none" stroke={GOLD} strokeWidth={36} opacity={.14} filter="url(#gl)"/>
  {Array.from({length:14},(_,i)=>{const n=(s*.18+i/14)%1;const visible=s<T.desaparecer?1:Math.max(0,1-progress(s,T.ocho,T.tierra)*.72);return <g key={i} opacity={visible}><circle cx={325+n*462} cy={900-170*Math.sin(Math.PI*n)} r={6+i%3} fill={GOLD} opacity={.23+.6*n}/><path d={'M '+(325+n*462-36)+' '+(900-170*Math.sin(Math.PI*n))+' h 29'} stroke={GOLD} strokeWidth="2" opacity={.4}/></g>})}
  <circle cx="310" cy="900" r="188" fill={GOLD} opacity={.11*sunFade} filter="url(#gl)"/>
  <g opacity={sunFade}><Disc x={310} y={900} r={147+Math.sin(s*1.5)*3} lit={true} s={s}/></g>
  <g opacity={1-sunFade}><circle cx="310" cy="900" r="147" stroke="#4c657e" strokeWidth="3" fill="#101a2b"/><circle cx="310" cy="900" r="120" fill="none" stroke="#264465" strokeWidth="2" strokeDasharray="7 13" opacity=".6"/></g>
  <Disc x={earthX} y={earthY} r={84} lit={false} s={s}/>
  <g transform={'translate('+earthX+' '+earthY+')'} opacity={.92}>
   <path d="M -35 -60 Q -5 -84 30 -50 L 17 -26 L 39 -3 L 12 16 L -6 7 L -20 -24 Z" fill="#76d5a2" opacity={.68}/>
   <path d="M -40 16 Q 4 5 39 34 L 12 61 L -28 52Z" fill="#76d5a2" opacity={.58}/>
  </g>
  <path d={'M 310 1090 L '+earthX+' '+(earthY+130)} stroke={CYAN} strokeWidth="3" opacity={.12+.25*g} strokeDasharray="10 15"/>
  <g opacity={show(s,T.ocho,T.ultimo+2)}>
   <path d={'M 313 900 L '+(313+472*travel)+' 900'} stroke={GOLD} strokeWidth="9" opacity=".92"/>
   <circle cx={313+472*travel} cy={900} r="17" fill="#fff5d1" stroke={GOLD} strokeWidth="5"/>
   <circle cx={313+472*travel} cy={900} r="45" fill={GOLD} opacity=".2"/>
  </g>
  <g opacity={show(s,T.gravedad,T.juntos+.5)}>
   {Array.from({length:5},(_,i)=><circle key={i} cx={310} cy={900} r={205+((s-T.gravedad)*128+i*68)%660} stroke={CYAN} strokeWidth="4" fill="none" opacity={.35*(1-i*.09)}/>)}
  </g>
  <circle cx={earthX} cy={earthY} r={105+Math.abs(pulse(s,T.tierra))*18} stroke={GOLD} strokeWidth="6" opacity={Math.abs(pulse(s,T.tierra))*.9} fill="none"/>
 </svg>
 <div style={{position:'absolute',top:75,left:55,right:55,display:'flex',justifyContent:'space-between',alignItems:'center',fontFamily:FONT,fontWeight:800,fontSize:31,letterSpacing:4,color:'#bed8ec'}}>
  <span>VARIADO / CIENCIA IMPOSIBLE</span><span style={{color:GOLD}}>01 — 07</span>
 </div>
 <div style={{position:'absolute',top:255,left:55,right:55,textAlign:'center',fontFamily:FONT,fontWeight:900,color:'#f2f8ff',fontSize:62,lineHeight:1.13,textShadow:'0 7px 32px #000'}}>
  {s< T.ocho?'¿Y SI EL SOL DESAPARECIERA?':v.n}
 </div>
 <div style={{position:'absolute',top:355,left:55,right:55,textAlign:'center',fontFamily:FONT,fontWeight:700,color:current===0?GOLD:CYAN,fontSize:30,letterSpacing:3}}>{v.detail}</div>
 <div style={{position:'absolute',top:1160,left:95,right:95,height:64,borderRadius:32,background:'rgba(15,36,59,.88)',border:'2px solid #416386'}}>
  <div style={{position:'absolute',inset:0,width:(6+Math.min(1,s/29)*94)+'%',borderRadius:32,background:'linear-gradient(90deg,#a75c22,#ffc96c)',opacity:.85}}/>
  <div style={{position:'absolute',left:26,top:11,fontFamily:FONT,fontSize:27,color:'#fff',fontWeight:900}}>TIEMPO QUE TARDA LA SEÑAL</div>
 </div>
 <div style={{position:'absolute',top:1260,left:120,right:120,textAlign:'center'}}>
   <div style={{fontFamily:FONT,fontWeight:900,fontSize:90,color:GOLD,textShadow:'0 0 35px #de9b3344'}}>{current===0?'00:00':current===6?'08:20':String(Math.floor(8*Math.max(.01,Math.min(1,s/29)))).padStart(2,'0')+':'+String(Math.floor((s*13)%60)).padStart(2,'0')}</div>
   <div style={{fontFamily:FONT,fontWeight:650,fontSize:28,letterSpacing:5,color:'#aed4f2'}}>DEL SOL A LA TIERRA</div>
 </div>
 <div style={{position:'absolute',top:1490,left:80,right:80,height:1,background:'#799eb04e'}}/>
 <div style={{position:'absolute',bottom:160,left:70,right:70,height:6,background:'#21415b',borderRadius:6}}><div style={{height:'100%',width:(100*Math.min(1,s/29))+'%',background:GOLD,borderRadius:6}}/></div>
 </AbsoluteFill>;
};
